{
  "name": "多维数据查看器",
  "name_en": "ND Data Viewer",
  "manufacturer": "",
  "description": "用于实验数据可视化的非物理软件组件。它面向多维数据的过滤、重排与显示，可根据均匀或非均匀采样数据选择合适的数据展示方式，并支持导航轴及最高到二维信号图像的显示，适合在实验过程中浏览和检查多维测量结果。",
  "description_en": "A non-physical software component for experimental data visualization. It filters, reshapes, and displays multidimensional data, selects suitable display logic for uniformly or non-uniformly spaced datasets, and supports navigation axes with signal display up to 2D images. It is used to browse and inspect multidimensional measurement results during experiments.",
  "actions": [
    {
      "action_name": "auto-update_data_displayer",
      "description": "根据数据分布类型更新数据展示组件。",
      "description_en": "Update the data displayer according to the data distribution type."
    },
    {
      "action_name": "auto-set_data_test",
      "description": "生成或设置用于查看器测试的示例多维数据。",
      "description_en": "Generate or set example multidimensional data for viewer testing."
    },
    {
      "action_name": "auto-update_widget_visibility",
      "description": "根据数据内容或导航索引更新界面控件的可见性。",
      "description_en": "Update widget visibility based on the data content or navigation indexes."
    },
    {
      "action_name": "auto-update_filters",
      "description": "更新用于数据处理或显示的数据过滤器。",
      "description_en": "Update the data filters used for processing or display."
    },
    {
      "action_name": "auto-show_settings",
      "description": "显示或隐藏查看器设置界面。",
      "description_en": "Show or hide the viewer settings interface."
    },
    {
      "action_name": "auto-prepare_ui",
      "description": "准备查看器用户界面。",
      "description_en": "Prepare the viewer user interface."
    },
    {
      "action_name": "auto-setup_actions",
      "description": "配置查看器可用的界面操作项。",
      "description_en": "Set up the available viewer UI actions."
    },
    {
      "action_name": "auto-reshape_data",
      "description": "将输入数据重排为适合显示的结构。",
      "description_en": "Reshape input data into a structure suitable for display."
    },
    {
      "action_name": "auto-connect_things",
      "description": "连接查看器内部的界面与逻辑信号。",
      "description_en": "Connect internal viewer UI elements and logic signals."
    },
    {
      "action_name": "auto-setup_widgets",
      "description": "创建并配置查看器界面控件。",
      "description_en": "Create and configure the viewer widgets."
    },
    {
      "action_name": "auto-update_data_dim",
      "description": "更新当前显示的数据维度。",
      "description_en": "Update the currently displayed data dimensionality."
    }
  ],
  "tag_hints": [
    "multidimensional data visualization",
    "scientific plotting",
    "navigation axes",
    "image display",
    "data filtering",
    "GUI viewer",
    "uniform and nonuniform data"
  ]
}

